571428\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"83.359375\" x2=\"95.359375\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"186.28571428571428\" y2=\"186.28571428571428\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(77.359375 192.28571428571428)\">300</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"89.359375\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"214.85714285714286\" y2=\"214.85714285714286\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"83.359375\" x2=\"95.359375\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"214.85714285714286\" y2=\"214.85714285714286\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(77.359375 220.85714285714286)\">200</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"89.359375\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"243.42857142857144\" y2=\"243.42857142857144\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"83.359375\" x2=\"95.359375\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"243.42857142857144\" y2=\"243.42857142857144\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(77.359375 249.42857142857144)\">100</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"89.359375\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"272\" y2=\"272\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"83.359375\" x2=\"95.359375\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"272\" y2=\"272\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(77.359375 278)\">0</text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\">Temperature (°C)</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"89.359375\" x2=\"89.359375\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"272\"></line><rect fill=\"#B3B3B3\" height=\"157\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"30.62673611111111\" x=\"119.98611111111111\" xmlns=\"http://www.w3.org/2000/svg\" y=\"115\"></rect><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(145.21947916666667 291.84) rotate(-40)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">L5_239</text><rect fill=\"#B3B3B3\" height=\"44.285714285714285\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"30.62673611111111\" x=\"181.23958333333334\" xmlns=\"http://www.w3.org/2000/svg\" y=\"227.71428571428572\"></rect><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(206.4729513888889 291.84) rotate(-40)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">K5_106</text><rect fill=\"#B3B3B3\" height=\"186.2285714285714\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"30.62673611111111\" x=\"242.49305555555557\" xmlns=\"http://www.w3.org/2000/svg\" y=\"85.7714285714286\"></rect><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(267.72642361111116 291.84) rotate(-40)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">K3_18</text><rect fill=\"#B3B3B3\" height=\"55.00000000000001\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"30.62673611111111\" x=\"303.74652777777777\" xmlns=\"http://www.w3.org/2000/svg\" y=\"217\"></rect><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(328.97989583333333 291.84) rotate(-40)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">K3_9</text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(227.1796875 24)\">Estimated Temperatures to which </text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(227.1796875 48)\">Evron Quarry Artifacts Were Exposed</text><rect fill=\"none\" height=\"26.84\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"95.97993469238281\" x=\"179.1897201538086\" xmlns=\"http://www.w3.org/2000/svg\" y=\"380.58056640625\"></rect><rect fill=\"#B3B3B3\" height=\"12\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"12\" x=\"186.1897201538086\" xmlns=\"http://www.w3.org/2000/svg\" y=\"387.58056640625\"></rect><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(205.1897201538086 399.58056640625)\">artifact</text></g></svg></figure></p>\n<p>Flint artifacts dating to 800,000 to 1,000,000 years ago have been recovered from the Evron Quarry in Israel. Likely created by the hominin <em>Homo erectus</em>, the artifacts have no visual features suggesting that they were exposed to fire, leading some scholars to conclude that these hominins had not acquired control of fire. But Zane Stepka and colleagues recently used a new method to determine whether these artifacts had been exposed to temperatures above 400°C (the typical temperature campfires reach) and concluded that the hominins who inhabited the site may have had control of fire. </p>","stem":"<p>Which choice best describes data in the graph that support the team&rsquo;s conclusion?</p>","answerOptions":[{"id":"67d5bedf-0e5e-46ad-8bde-3290d26c8681","content":"<p>Artifacts K5_106 and K3_9 were exposed to temperatures above 400&deg;C.</p>"},{"id":"ebe72203-b52a-4794-83bd-1da86485a0c2","content":"<p>Artifacts L5_239 and K3_18 were exposed to temperatures of approximately 550&deg;C and 650&deg;C, respectively.</p>"},{"id":"14ce7521-a013-4843-a8af-045cb762b630","content":"<p>All of the artifacts were exposed to temperatures above 100&deg;C.</p>"},{"id":"2f302f17-76c5-46de-bfd4-122b0eba146e","content":"<p>Artifact K3_9 was exposed to a higher temperature than was artifact K5_106.</p>"}],"keys":["ebe72203-b52a-4794-83bd-1da86485a0c2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. Campfires typically reach over 400&deg;C, so human artifacts that were exposed to temperatures higher than this may indicate some human control over fire. </p><p>Choice A is incorrect. This choice misreads the graph. Neither artifact K3_9 nor K5_106 was exposed to temperatures above even 200&deg;C. Choice C is incorrect. This choice doesn&rsquo;t support the claim. Campfires typically reach over 400&deg;C, so exposure to temperatures of 100&deg;C wouldn&rsquo;t demonstrate exposure to fire. Choice D is incorrect. This choice doesn&rsquo;t support the claim. Both artifacts K3_9 and K5_106 were exposed to temperatures of less than 200&deg;C. Since campfires typically reach over 400&deg;C, this wouldn&rsquo;t demonstrate exposure to fire. </p>","parenttemplatename":"OSP-KA-QUA-M007","parenttemplateid":"","templateclusterid":"4254baa7-34ca-420c-bb76-95798c121ca2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$7f0be746$SATQ$, $SATQ$29cada86-74bb-41bb-a0dd-9a24a165a4e5$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Milan Kundera&rsquo;s 1984 novel <em>The Unbearable Lightness of Being</em> (translated by Michael Henry Heim in 1984). Karenin is a dog that belongs to Tomas and Tereza.</p>
<blockquote>
<p>Karenin was not overjoyed by the move to Switzerland [from Prague]. Karenin hated change. Dog time cannot be plotted along a straight line; it does not move on and on, from one thing to the next. It moves in a circle like the hands of a clock, which&mdash;they, too, unwilling to dash madly ahead&mdash;turn round and round the face, day in and day out following the same path. In Prague, when Tomas and Tereza bought a new chair or moved a flower pot, Karenin would look on in displeasure. It disturbed his sense of time. It was as though they were trying to dupe the hands of the clock by changing the numbers on its face.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;1984 by Milan Kundera. Translation &copy;1984 by Harper &amp; Row, Publishers, Inc.</span></p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"46e44a65-b0c1-42e1-b4f2-5919f0e7cdd6","content":"<p>As a dog, Karenin possesses a sense of time that involves a strong preference for predictability and an aversion to disruption.</p>"},{"id":"c37fb2cf-c8c2-4402-9895-183c2b457f93","content":"<p>After he&rsquo;s moved to a new home, Karenin&rsquo;s negative response to changes has become more pronounced.</p>"},{"id":"afc286ca-ea6c-4390-be02-ff18cdd745e1","content":"<p>Similar to Tomas and Tereza, Karenin comprehends time as circular rather than as a straightforward progression.</p>"},{"id":"c7a2d308-4fea-45ca-a397-74b62192603c","content":"<p>As is the case for other dogs, Karenin&rsquo;s sense of time seems to accelerate depending on the objects and places that surround him.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["46e44a65-b0c1-42e1-b4f2-5919f0e7cdd6"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main idea of the text. The text begins by stating that Tomas and Tereza&rsquo;s dog Karenin felt disrupted by a recent move because of his dislike of change. The text then goes on to suggest that this is because the way a dog experiences time differs from the way humans experience time: time for a dog doesn&rsquo;t move linearly, going "on and on, from one thing to the next," but instead moves circularly, "like the hands of a clock." That is, time for a dog is experienced as a cyclical pattern characterized by routine and predictability, with each day "following the same path." The text then concludes by providing examples of seemingly insignificant changes in routine that profoundly "disturbed [Karenin&rsquo;s] sense of time," causing him to feel displeasure. Thus, the main idea of the text is that Karenin&rsquo;s sense of time as a dog involves a strong preference for predictability and an aversion to disruption.</p><p>Choice B is incorrect. Although the text emphasizes Karenin&rsquo;s displeasure with the recent move to a new home, it doesn&rsquo;t suggest that the move has made his negative responses more pronounced than they once were. Rather, in accounting for Karenin&rsquo;s displeasure with the move to Switzerland, the text explains that Karenin generally has a negative response to any kind of change. Choice C is incorrect because the text doesn&rsquo;t suggest that Karenin comprehends time similarly to how Tomas and Tereza comprehend it. On the contrary, the text strongly implies a contrast between dogs&rsquo; circular experience of time with the way humans experience time as a straightforward progression that can be "plotted on a straight line." Choice D is incorrect because the text provides no indication that a change in the places and objects surrounding Karenin causes him to feel as though time is accelerating. Although the text does use the language of "dash[ing] madly ahead" in relation to time, the phrase appears in the context of a comparison illustrating how dogs experience time: time for a dog moves just as the hands of a clock do, in a circle and "unwilling to dash madly ahead"&mdash;that is, always in a regular and predictable way.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"7f0be746","external_id":"29cada86-74bb-41bb-a0dd-9a24a165a4e5","vaultid":null,"uId":"6d89a581-c713-4103-a4e2-3d6e82009054","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is from Milan Kundera&rsquo;s 1984 novel <em>The Unbearable Lightness of Being</em> (translated by Michael Henry Heim in 1984). Karenin is a dog that belongs to Tomas and Tereza.</p>\n<blockquote>\n<p>Karenin was not overjoyed by the move to Switzerland [from Prague]. Karenin hated change. Dog time cannot be plotted along a straight line; it does not move on and on, from one thing to the next. It moves in a circle like the hands of a clock, which&mdash;they, too, unwilling to dash madly ahead&mdash;turn round and round the face, day in and day out following the same path. In Prague, when Tomas and Tereza bought a new chair or moved a flower pot, Karenin would look on in displeasure. It disturbed his sense of time. It was as though they were trying to dupe the hands of the clock by changing the numbers on its face.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;1984 by Milan Kundera. Translation &copy;1984 by Harper &amp; Row, Publishers, Inc.</span></p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"46e44a65-b0c1-42e1-b4f2-5919f0e7cdd6","content":"<p>As a dog, Karenin possesses a sense of time that involves a strong preference for predictability and an aversion to disruption.</p>"},{"id":"c37fb2cf-c8c2-4402-9895-183c2b457f93","content":"<p>After he&rsquo;s moved to a new home, Karenin&rsquo;s negative response to changes has become more pronounced.</p>"},{"id":"afc286ca-ea6c-4390-be02-ff18cdd745e1","content":"<p>Similar to Tomas and Tereza, Karenin comprehends time as circular rather than as a straightforward progression.</p>"},{"id":"c7a2d308-4fea-45ca-a397-74b62192603c","content":"<p>As is the case for other dogs, Karenin&rsquo;s sense of time seems to accelerate depending on the objects and places that surround him.</p>"}],"keys":["46e44a65-b0c1-42e1-b4f2-5919f0e7cdd6"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main idea of the text. The text begins by stating that Tomas and Tereza&rsquo;s dog Karenin felt disrupted by a recent move because of his dislike of change. The text then goes on to suggest that this is because the way a dog experiences time differs from the way humans experience time: time for a dog doesn&rsquo;t move linearly, going \"on and on, from one thing to the next,\" but instead moves circularly, \"like the hands of a clock.\" That is, time for a dog is experienced as a cyclical pattern characterized by routine and predictability, with each day \"following the same path.\" The text then concludes by providing examples of seemingly insignificant changes in routine that profoundly \"disturbed [Karenin&rsquo;s] sense of time,\" causing him to feel displeasure. Thus, the main idea of the text is that Karenin&rsquo;s sense of time as a dog involves a strong preference for predictability and an aversion to disruption.</p><p>Choice B is incorrect. Although the text emphasizes Karenin&rsquo;s displeasure with the recent move to a new home, it doesn&rsquo;t suggest that the move has made his negative responses more pronounced than they once were. Rather, in accounting for Karenin&rsquo;s displeasure with the move to Switzerland, the text explains that Karenin generally has a negative response to any kind of change. Choice C is incorrect because the text doesn&rsquo;t suggest that Karenin comprehends time similarly to how Tomas and Tereza comprehend it. On the contrary, the text strongly implies a contrast between dogs&rsquo; circular experience of time with the way humans experience time as a straightforward progression that can be \"plotted on a straight line.\" Choice D is incorrect because the text provides no indication that a change in the places and objects surrounding Karenin causes him to feel as though time is accelerating. Although the text does use the language of \"dash[ing] madly ahead\" in relation to time, the phrase appears in the context of a comparison illustrating how dogs experience time: time for a dog moves just as the hands of a clock do, in a circle and \"unwilling to dash madly ahead\"&mdash;that is, always in a regular and predictable way.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323041,"updateDate":1730147323041}$SATQ$::jsonb, 1730147323041, 1730147323041),
    ($SATQ$7f293254$SATQ$, $SATQ$bf4990d3-7a3a-49ff-b7dc-8ba4cf811d16$SATQ$::uuid, $SATQ$17bb6acf-9a9b-4213-9cc4-96cf89fe9eaf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Art collectives, like the United States- and Vietnam-based collective The Propeller Group or Cuba&rsquo;s Los Carpinteros, are groups of artists who agree to work together: perhaps for stylistic reasons, or to advance certain shared political ideals, or to help mitigate the costs of supplies and studio space. Regardless of the reasons, art collectives usually involve some collaboration among the artists. Based on a recent series of interviews with various art collectives, an arts journalist claims that this can be difficult for artists who are often used to having sole control over their work.</p>$SATQ$, $SATQ$<p>Which quotation from the interviews best illustrates the journalist&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"a3d427c1-98fa-4950-9f1e-7e3f915d6d8f","content":"<p>&ldquo;The first collective I joined included many amazingly talented artists, and we enjoyed each other&rsquo;s company, but because we had a hard time sharing credit and responsibility for our work, the collective didn&rsquo;t last.&rdquo;&nbsp;</p>"},{"id":"afa29749-f4be-438e-b501-760b96758925","content":"<p>&ldquo;We work together, but that doesn&rsquo;t mean that individual projects are equally the work of all of us. Many of our projects are primarily the responsibility of whoever originally proposed the work to the group.&rdquo;</p>"},{"id":"d67f753a-939c-4bfb-850f-29966c9f548f","content":"<p>&ldquo;Having worked as a member of a collective for several years, it&rsquo;s sometimes hard to recall what it was like to work alone without the collective&rsquo;s support. But that support encourages my individual expression rather than limits it.&rdquo;</p>"},{"id":"744c90f6-98e3-4cd1-9f45-d2c3f9d7f9f5","content":"<p>&ldquo;Sometimes an artist from outside the collective will choose to collaborate with us on a project, but all of those projects fit within the larger themes of the work the collective does on its own.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a3d427c1-98fa-4950-9f1e-7e3f915d6d8f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the quotation that best illustrates the journalist&rsquo;s claim. By indicating that a collective didn&rsquo;t continue because it was hard to share credit and responsibilities within the group even though the company was enjoyable, the quotation shows that working collaboratively can be difficult for artists who are used to having complete control over their work. </p><p>Choice B is incorrect because the quotation indicates that members of a collective are able to collaborate together and have agreed on a fair way to manage their responsibilities; this doesn&rsquo;t demonstrate the challenge of sharing control among members of a collective. Choice C is incorrect because the quotation highlights the support and encouragement of individual expression an artist experiences due to working in a collective; these positive aspects don&rsquo;t demonstrate the challenge of sharing control among members of a collective. Choice D is incorrect because the quotation doesn&rsquo;t address any challenges of sharing control among members of a collective; it simply indicates that artists sometimes choose to work with collectives without having to be a member. Therefore, the quotation doesn&rsquo;t illustrate the journalist&rsquo;s claim.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-308-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$17ce3a35-61d7-4f1a-bce3-c6328ca10743$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7f293254","external_id":"bf4990d3-7a3a-49ff-b7dc-8ba4cf811d16","vaultid":"17bb6acf-9a9b-4213-9cc4-96cf89fe9eaf","uId":"b94d76d2-68d2-4964-a997-c8349c3e9673","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Art collectives, like the United States- and Vietnam-based collective The Propeller Group or Cuba&rsquo;s Los Carpinteros, are groups of artists who agree to work together: perhaps for stylistic reasons, or to advance certain shared political ideals, or to help mitigate the costs of supplies and studio space. Regardless of the reasons, art collectives usually involve some collaboration among the artists. Based on a recent series of interviews with various art collectives, an arts journalist claims that this can be difficult for artists who are often used to having sole control over their work.</p>","stem":"<p>Which quotation from the interviews best illustrates the journalist&rsquo;s claim?</p>","answerOptions":[{"id":"a3d427c1-98fa-4950-9f1e-7e3f915d6d8f","content":"<p>&ldquo;The first collective I joined included many amazingly talented artists, and we enjoyed each other&rsquo;s company, but because we had a hard time sharing credit and responsibility for our work, the collective didn&rsquo;t last.&rdquo;&nbsp;</p>"},{"id":"afa29749-f4be-438e-b501-760b96758925","content":"<p>&ldquo;We work together, but that doesn&rsquo;t mean that individual projects are equally the work of all of us. Many of our projects are primarily the responsibility of whoever originally proposed the work to the group.&rdquo;</p>"},{"id":"d67f753a-939c-4bfb-850f-29966c9f548f","content":"<p>&ldquo;Having worked as a member of a collective for several years, it&rsquo;s sometimes hard to recall what it was like to work alone without the collective&rsquo;s support. But that support encourages my individual expression rather than limits it.&rdquo;</p>"},{"id":"744c90f6-98e3-4cd1-9f45-d2c3f9d7f9f5","content":"<p>&ldquo;Sometimes an artist from outside the collective will choose to collaborate with us on a project, but all of those projects fit within the larger themes of the work the collective does on its own.&rdquo;</p>"}],"keys":["a3d427c1-98fa-4950-9f1e-7e3f915d6d8f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the quotation that best illustrates the journalist&rsquo;s claim. By indicating that a collective didn&rsquo;t continue because it was hard to share credit and responsibilities within the group even though the company was enjoyable, the quotation shows that working collaboratively can be difficult for artists who are used to having complete control over their work. </p><p>Choice B is incorrect because the quotation indicates that members of a collective are able to collaborate together and have agreed on a fair way to manage their responsibilities; this doesn&rsquo;t demonstrate the challenge of sharing control among members of a collective. Choice C is incorrect because the quotation highlights the support and encouragement of individual expression an artist experiences due to working in a collective; these positive aspects don&rsquo;t demonstrate the challenge of sharing control among members of a collective. Choice D is incorrect because the quotation doesn&rsquo;t address any challenges of sharing control among members of a collective; it simply indicates that artists sometimes choose to work with collectives without having to be a member. Therefore, the quotation doesn&rsquo;t illustrate the journalist&rsquo;s claim.&nbsp;</p>","parenttemplatename":"OSP-308-TXT","parenttemplateid":"","templateclusterid":"17ce3a35-61d7-4f1a-bce3-c6328ca10743","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$7fdba7ad$SATQ$, $SATQ$b9c67542-abcb-413f-b2ae-e3f7d26e431f$SATQ$::uuid, $SATQ$5768a024-66c1-4d4e-8e0c-fce615e7fc62$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The Milky Way galaxy is composed of millions of stars in a relatively flat structure containing a thin disk and a thick disk. Based on computer simulations and analysis of data on the brightness, position, and chemical composition of about 250,000 stars in the thick disk (collected from two telescopes, one in China and one orbiting in space), astrophysicists Maosheng Xiang and Hans-Walter Rix claim that the thick disk of the Milky Way formed in two distinct phases rather than a single one.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the researchers&rsquo; claim?</p>$SATQ$, $SATQ$[{"id":"3eb60aeb-b3da-4d97-b8af-795b8e48f87d","content":"<p>The telescopes used by the researchers have detected stars of similar ages in galaxies other than the Milky Way.</p>"},{"id":"ee69a1ab-909d-4ba4-8b9c-7dca82424c88","content":"<p>There&rsquo;s an age difference of about 2 billion years between certain stars in the thick disk.</p>"},{"id":"b33d47a7-d5c3-4394-b9ba-7d9e7482a5c0","content":"<p>The thin disk contains about twice as many stars that can be seen from Earth as the thick disk does.</p>"},{"id":"70e94b7b-93eb-4068-ac3f-4e3d81478a9e","content":"<p>The stars in the Milky Way tend to have very similar chemical compositions.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["ee69a1ab-909d-4ba4-8b9c-7dca82424c88"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. A consistent age difference of 2 billion years between certain stars within the thick disk would support the claim that the thick disk formed in two phases instead of one, with the second phase beginning 2 billion years after the first phase. </p><p>Choice A is incorrect. This choice doesn&rsquo;t support the claim. The researchers base their claim on their study of stars inside the thick disk of the Milky Way. This choice makes a comparison to stars in other galaxies, which isn&rsquo;t relevant. Choice C is incorrect. This choice doesn&rsquo;t support the claim. The researchers base their claim on their study of stars inside the thick disk. This choice makes a comparison to the thin disk, which isn&rsquo;t relevant. Choice D is incorrect. This choice doesn&rsquo;t support the claim. It&rsquo;s too general. The claim is specifically about the thick disk. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-E004$SATQ$, $SATQ$$SATQ$, $SATQ$01679c72-5df4-4c71-9b90-eb61f505f5e7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7fdba7ad","external_id":"b9c67542-abcb-413f-b2ae-e3f7d26e431f","vaultid":"5768a024-66c1-4d4e-8e0c-fce615e7fc62","uId":"ce44968e-e118-4fe7-bd50-e0f9f567be19","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The Milky Way galaxy is composed of millions of stars in a relatively flat structure containing a thin disk and a thick disk. Based on computer simulations and analysis of data on the brightness, position, and chemical composition of about 250,000 stars in the thick disk (collected from two telescopes, one in China and one orbiting in space), astrophysicists Maosheng Xiang and Hans-Walter Rix claim that the thick disk of the Milky Way formed in two distinct phases rather than a single one.</p>","stem":"<p>Which finding, if true, would most directly support the researchers&rsquo; claim?</p>","answerOptions":[{"id":"3eb60aeb-b3da-4d97-b8af-795b8e48f87d","content":"<p>The telescopes used by the researchers have detected stars of similar ages in galaxies other than the Milky Way.</p>"},{"id":"ee69a1ab-909d-4ba4-8b9c-7dca82424c88","content":"<p>There&rsquo;s an age difference of about 2 billion years between certain stars in the thick disk.</p>"},{"id":"b33d47a7-d5c3-4394-b9ba-7d9e7482a5c0","content":"<p>The thin disk contains about twice as many stars that can be seen from Earth as the thick disk does.</p>"},{"id":"70e94b7b-93eb-4068-ac3f-4e3d81478a9e","content":"<p>The stars in the Milky Way tend to have very similar chemical compositions.</p>"}],"keys":["ee69a1ab-909d-4ba4-8b9c-7dca82424c88"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. A consistent age difference of 2 billion years between certain stars within the thick disk would support the claim that the thick disk formed in two phases instead of one, with the second phase beginning 2 billion years after the first phase. </p><p>Choice A is incorrect. This choice doesn&rsquo;t support the claim. The researchers base their claim on their study of stars inside the thick disk of the Milky Way. This choice makes a comparison to stars in other galaxies, which isn&rsquo;t relevant. Choice C is incorrect. This choice doesn&rsquo;t support the claim. The researchers base their claim on their study of stars inside the thick disk. This choice makes a comparison to the thin disk, which isn&rsquo;t relevant. Choice D is incorrect. This choice doesn&rsquo;t support the claim. It&rsquo;s too general. The claim is specifically about the thick disk. </p>","parenttemplatename":"OSP-KA-TXT-E004","parenttemplateid":"","templateclusterid":"01679c72-5df4-4c71-9b90-eb61f505f5e7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$7ffae38a$SATQ$, $SATQ$8ae4f9b3-f842-46f5-bc37-368fe0f440ca$SATQ$::uuid, $SATQ$efe7cccc-0277-49e6-aaab-67d1df41fb4f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Jack London&rsquo;s 1903 novel <em>The Call of the Wild</em>. Buck is a sled dog living with John Thornton in Yukon, Canada.</p>
<p style='padding-left: 1em;'>Thornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton&rsquo;s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting. </p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"383d6e55-4f9b-4fb0-89a2-b8385aae3ce9","content":"<p>Buck has become less social since he began living with Thornton.</p>"},{"id":"fa969027-81a0-4011-b8af-ef7e4fb08ace","content":"<p>Buck mistrusts humans and does his best to avoid them.</p>"},{"id":"f408ec59-1050-488f-abd4-a8c72727a99d","content":"<p>Buck has been especially well liked by most of Thornton&rsquo;s friends.</p>"},{"id":"29497cbf-73aa-40e0-bfe7-89748af7fb00","content":"<p>Buck holds Thornton in higher regard than any other person.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["29497cbf-73aa-40e0-bfe7-89748af7fb00"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately states the main idea of the text. After establishing that Buck views most people &ldquo;as nothing,&rdquo; the text explains that Buck won&rsquo;t acknowledge people other than Thornton unless they appear friendly toward Thornton, and even then he&rsquo;s only reluctantly accepting. Thus, the text focuses on the idea that Thornton has a special status in Buck&rsquo;s mind, with Buck holding him in higher regard than other people. </p><p>Choice A is incorrect because the text conveys that Buck isn&rsquo;t social with people other than Thornton but doesn&rsquo;t address Buck&rsquo;s life or temperament before he lived with Thornton. Choice B is incorrect because the text conveys that Buck doesn&rsquo;t really care about people other than Thornton and is aloof toward them. However, there&rsquo;s no indication that Buck mistrusts and avoids people generally; indeed, he accepts Thornton, who is a human. Choice C is incorrect because the text refers to random travelers praising and petting Buck and Thornton&rsquo;s partners giving Buck favors, but there&rsquo;s no indication that any of these people are Thornton&rsquo;s friends or that they have a particular fondness for Buck. </p>$SATQ$, false, 0, $SATQ$OSP-020-CID$SATQ$, $SATQ$$SATQ$, $SATQ$d751946a-b6e1-4766-b6f9-d4eb5cb73d36$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7ffae38a","external_id":"8ae4f9b3-f842-46f5-bc37-368fe0f440ca","vaultid":"efe7cccc-0277-49e6-aaab-67d1df41fb4f","uId":"de55e61c-ae3f-4b6f-9d19-f9a1752107da","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The following text is adapted from Jack London&rsquo;s 1903 novel <em>The Call of the Wild</em>. Buck is a sled dog living with John Thornton in Yukon, Canada.</p>\n<p style='padding-left: 1em;'>Thornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton&rsquo;s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting. </p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"383d6e55-4f9b-4fb0-89a2-b8385aae3ce9","content":"<p>Buck has become less social since he began living with Thornton.</p>"},{"id":"fa969027-81a0-4011-b8af-ef7e4fb08ace","content":"<p>Buck mistrusts humans and does his best to avoid them.</p>"},{"id":"f408ec59-1050-488f-abd4-a8c72727a99d","content":"<p>Buck has been especially well liked by most of Thornton&rsquo;s friends.</p>"},{"id":"29497cbf-73aa-40e0-bfe7-89748af7fb00","content":"<p>Buck holds Thornton in higher regard than any other person.</p>"}],"keys":["29497cbf-73aa-40e0-bfe7-89748af7fb00"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately states the main idea of the text. After establishing that Buck views most people &ldquo;as nothing,&rdquo; the text explains that Buck won&rsquo;t acknowledge people other than Thornton unless they appear friendly toward Thornton, and even then he&rsquo;s only reluctantly accepting. Thus, the text focuses on the idea that Thornton has a special status in Buck&rsquo;s mind, with Buck holding him in higher regard than other people. </p><p>Choice A is incorrect because the text conveys that Buck isn&rsquo;t social with people other than Thornton but doesn&rsquo;t address Buck&rsquo;s life or temperament before he lived with Thornton. Choice B is incorrect because the text conveys that Buck doesn&rsquo;t really care about people other than Thornton and is aloof toward them. However, there&rsquo;s no indication that Buck mistrusts and avoids people generally; indeed, he accepts Thornton, who is a human. Choice C is incorrect because the text refers to random travelers praising and petting Buck and Thornton&rsquo;s partners giving Buck favors, but there&rsquo;s no indication that any of these people are Thornton&rsquo;s friends or that they have a particular fondness for Buck. </p>","parenttemplatename":"OSP-020-CID","parenttemplateid":"","templateclusterid":"d751946a-b6e1-4766-b6f9-d4eb5cb73d36","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959316,"updateDate":1691007959316}$SATQ$::jsonb, 1691007959316, 1691007959316),
