-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"82.28598213195801\" y1=\"272\" x2=\"94.28598213195801\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(76.28598213195801 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Number of submissions</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"88.28598213195801\" y1=\"72\" x2=\"88.28598213195801\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"122.87523436546326\" x2=\"122.87523436546326\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(122.87523436546326 291.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2016</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"192.05373883247375\" x2=\"192.05373883247375\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(192.05373883247375 291.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2017</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"261.23224329948425\" x2=\"261.23224329948425\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(261.232243299